// Additional source-unit/current-inventory assertions; old122 callbacks retained.
function sourcePointer(o, p) {
  for (const part of p.split('/').slice(1)) o = o[part.replace(/~1/g, '/').replace(/~0/g, '~')];
  return o;
}
function nativeProjection(s) {
  return s.replace(/<(style|script)\b[^>]*>[\s\S]*?<\/\1>/gi, '')
    .replace(/<[^>]*>/g, '').replace(/&(?:#[xX][0-9a-fA-F]+|#[0-9]+|[a-zA-Z][a-zA-Z0-9]+);/g,
      e => Object.hasOwn(NATIVE_ENTITIES, e) ? NATIVE_ENTITIES[e] : e);
}
function nativeUnits(h, partition) {
  const heads = [...h.matchAll(/<h[1-6]\b[^>]*>([\s\S]*?)<\/h[1-6]>/g)];
  const paragraphs = [...h.matchAll(/<p\b[^>]*>([\s\S]*?)<\/p>/g)];
  const regex = partition === 'bamidbar' ? /<(?<tag>p|li)\b[^>]*>(?<inner>[\s\S]*?)<\/\k<tag>>/dg : /<(?<tag>p)\b[^>]*>(?<inner>[\s\S]*?)<\/\k<tag>>/dg;
  return [...h.matchAll(regex)].map((m, i) => {
    const headingMatch = heads.filter(x => x.index < m.index).at(-1);
    let heading = headingMatch ? nativeProjection(headingMatch[1]) : null;
    if (partition !== 'bamidbar' && heading !== null) heading = heading.replaceAll('[עריכה]', '').trim();
    const stream = [['רעיא מהימנא', partition === 'bamidbar' ? 'raaya' : 'raaya-meheimna'], ['סתרי תורה','sitrei-torah'], ['תוספתא','tosefta'], ['מדרש הנעלם','midrash-neelam']].find(([mark]) => heading && heading.includes(mark))?.[1] || 'main';
    const text = nativeProjection(m.groups.inner), left = text.trimStart(); let excludedReason = null;
    if (!text.trim()) excludedReason = 'empty';
    else if (['<<','«','מתוך:'].some(x => left.startsWith(x))) excludedReason = 'navigation';
    else if (partition === 'bamidbar' && heading && ['הערות','תרגום'].some(x => heading.includes(x))) excludedReason = 'apparatus';
    else if (partition === 'bamidbar' && m.groups.tag === 'li' && (heading === null || heading === 'תוכן עניינים')) excludedReason = 'toc-navigation';
    else if (['bamidbar','devarim'].includes(partition) && ['(הדף','(אין רעיא','(אחרי זה שייך','(בדפוס ווילנא', ...(partition === 'devarim' ? ['(אין זהר','(בנוסחאות הישנות'] : [])].some(x => left.startsWith(x))) excludedReason = 'editorial-insertion';
    else if (partition === 'devarim' && left.startsWith('הפניה ל:')) excludedReason = 'redirect-shell';
    else if (partition === 'devarim' && heading && ['הערות שוליים','תרגום'].some(x => heading.includes(x))) excludedReason = 'apparatus';
    const [a,z] = m.indices.groups.inner;
    return {nativeParagraphIndex: m.groups.tag === 'p' ? paragraphs.findIndex(p => p.index === m.index) : null,
      nativeBlockIndex:i, nativeElementName:m.groups.tag, heading, stream, text, innerHTML:m.groups.inner, excludedReason,
      htmlBounds:[Array.from(h.slice(0,a)).length,Array.from(h.slice(0,z)).length]};
  });
}
const ownerUnits = {};
test('PRIVATE131 complete62 native JSON owners + all source units/streams/whole-body hashes independently authenticated', () => {
  assert.equal(Object.keys(SOURCE_OWNERS).length, 62);
  for (const [hash, o] of Object.entries(SOURCE_OWNERS)) {
    const raw = Buffer.from(o.rawResponseBase64, 'base64'); assert.equal(sha(raw), hash); assert.equal(raw.length,o.sourcePin.bytes);
    const obj = JSON.parse(raw), h = sourcePointer(obj,o.jsonPointer), parse = (obj.native || obj).parse;
    assert.equal(parse.title,o.title); assert.equal(parse.revid ?? null,o.revision); assert.equal(h,o.nativeHTML); assert.equal(sha(h),o.nativeHTMLSha256);
    const units = nativeUnits(h,o.partition); ownerUnits[hash] = units;
    assert.equal(units.length,o.allUnits.length);
    units.forEach((u,i) => {
      const e = o.allUnits[i];
      for (const k of ['nativeParagraphIndex','nativeBlockIndex','nativeElementName','heading','stream','excludedReason']) assert.deepEqual(u[k],e[k]);
      assert.deepEqual(u.htmlBounds,e.htmlBounds); assert.equal(sha(u.text),e.unitSha256Utf8); assert.equal(sha(u.innerHTML),e.innerHTMLSha256);
    });
    assert.equal(sha(units.map(u=>u.text).join('\n')),o.allUnitsNewlineJoinedSha256Utf8);
    assert.equal(sha(units.filter(u=>u.excludedReason===null).map(u=>u.text).join('\n')),o.bodyUnitsNewlineJoinedSha256Utf8);
  }
});
