test('PRIVATE131 independently ordered all substantive p/li source units across amud seams with original native headed streams', () => {
  for(const e of NEW131_EXPECTED) {
    const r=data.days[e.key],first=r.spans[0],last=r.spans.at(-1), expected=[];
    const n0=first.daf*2+first.amud-1,n1=last.daf*2+last.amud-1;
    for(let n=n0;n<=n1;n++) {
      const spans=r.spans.filter(s=>s.daf*2+s.amud-1===n);assert.ok(spans.length>0);
      const owner=spans[0].sourceSha256;
      for(const u of ownerUnits[owner]) {
        if(n===n0 && u.nativeBlockIndex<first.nativeBlockIndex || n===n1 && u.nativeBlockIndex>last.nativeBlockIndex)continue;
        if(u.excludedReason!==null || u.stream!==first.stream)continue;
        const a=n===n0 && u.nativeBlockIndex===first.nativeBlockIndex?first.startOffset:0;
        const z=n===n1 && u.nativeBlockIndex===last.nativeBlockIndex?last.endOffsetExclusive:Array.from(u.text).length;
        if(z>a)expected.push([owner,u.nativeBlockIndex,a,z]);
      }
    }
    assert.deepEqual(r.spans.map(s=>[s.sourceSha256,s.nativeBlockIndex,s.startOffset,s.endOffsetExclusive]),expected);
  }
});
