// PRIVATE133 new native corpus controls. Fixtures are frozen independently from
// complete authenticated source owners, never loaded from private paths/network.
const PRIVATE133_UNITS = {};
function validate133Owner(o, frozenHash) {
  const bytes=Buffer.from(o.rawResponseBase64,'base64');
  assert.equal(sha(bytes),frozenHash);assert.equal(bytes.length,o.sourcePin.bytes);
  const obj=JSON.parse(bytes), h=sourcePointer(obj,o.jsonPointer);
  assert.equal(obj.parse.title,o.title);assert.equal(obj.parse.revid,o.revision);
  assert.equal(sha(h),o.nativeHTMLSha256);
  const units=nativeUnits(h,'bereishit');
  assert.equal(units.length,o.units.length);
  units.forEach((u,i)=>{
    const e=o.units[i];assert.equal(u.nativeParagraphIndex,e.nativeP);assert.equal(u.nativeElementName,'p');
    assert.equal(u.text,e.text);assert.equal(sha(u.text),e.textSha256Utf8);
    assert.equal(u.innerHTML,e.innerHTML);assert.equal(sha(u.innerHTML),e.innerHTMLSha256);
    assert.deepEqual(u.htmlBounds,e.htmlBounds);assert.equal(u.stream,e.stream);assert.equal(u.heading,e.heading);
    assert.equal(Array.from(u.text).length,u.text.length,'complete source unit BMP, codepoint/UTF16 equality');
  });
  assert.equal(sha(units.map(u=>u.text).join('\n')),o.allParagraphTextJoinedSha256);
  return units;
}
function assert133Selection(row) {
  const expected=PRIVATE133.expected.find(e=>e.key===row.key);assert.ok(expected);
  assert.equal(row.fieldRole,'original-source');assert.equal(row.rawBodySha256Utf8,expected.bodyHash);
  assert.equal(row.spans.length,expected.spanHashes.length);
  assert.deepEqual(copy(row.spans.map(s=>[s.sourceSha256,s.nativeParagraphIndex,s.startOffset,s.endOffsetExclusive])),PRIVATE133.reviewedOrderedSpans[row.key]);
  row.spans.forEach((s,i)=>{
    const o=PRIVATE133.owners[s.sourceSha256];assert.ok(o);
    const u=PRIVATE133_UNITS[s.sourceSha256].find(u=>u.nativeParagraphIndex===s.nativeParagraphIndex);assert.ok(u);
    assert.equal(u.nativeElementName,'p');assert.equal(s.sourceUnitType,undefined);assert.equal(s.nativeBlockIndex,undefined);
    assert.equal(s.nativeElementName,undefined,'legacy paragraph projection: no invented block index/type');
    assert.equal(s.stream,u.stream);assert.equal(s.heading,u.heading);assert.equal(s.stream,'main');
    assert.equal(s.sourceTitle,o.title);assert.equal(s.sourceRevision,o.revision);assert.equal(s.sourceJsonPointer,o.jsonPointer);
    assert.equal(s.sourceNativeHTMLSha256,o.nativeHTMLSha256);assert.equal(s.innerHTMLSha256,sha(u.innerHTML));
    assert.equal(s.paragraphSha256Utf8,sha(u.text));assert.equal(s.entityPolicy,'decode');
    const literal=Array.from(u.text).slice(s.startOffset,s.endOffsetExclusive).join('');
    assert.equal(literal,s.rawText);assert.equal(sha(literal),expected.spanHashes[i]);
    assert.equal(sha(JSON.stringify(spanIdentity(s))),expected.identityHashes[i]);
    // Genuine positional conservation, not comparing only lengths/digests.
    Array.from(s.rawText).forEach((c,j)=>assert.equal(c,Array.from(u.text)[s.startOffset+j]));
  });
  assert.equal(sha(row.spans.map(s=>s.rawText).join('\n')),expected.bodyHash);
  assert.equal(sha(JSON.stringify(row)),expected.rowHash);
}
function rehash133(row) {
  row.spans.forEach((s,i)=>{s.ordinal=i;s.selectedSha256Utf8=sha(s.rawText);});
  row.rawBodySha256Utf8=sha(row.spans.map(s=>s.rawText).join('\n'));
}
