test('PRIVATE133 Tuesday complete retained/excluded/outside clause partition with repeated question and sole exclusion',()=>{
  const r=data.days['נח|יום שלישי'];assert133Selection(r);
  assert.deepEqual(r.spans.map(s=>[s.daf,s.amud,s.nativeParagraphIndex,s.startOffset,s.endOffsetExclusive]),[[61,2,9,336,409],[62,1,3,0,878],[62,1,3,1006,1205]]);
  const unit=PRIVATE133_UNITS[r.spans[1].sourceSha256].find(u=>u.nativeParagraphIndex===3).text;
  const coverage=Array.from(unit,()=>0);for(const s of r.spans.slice(1))for(let j=s.startOffset;j<s.endOffsetExclusive;j++)coverage[j]++;
  let prior=0;
  for(const c of PRIVATE133.tuesdayClauses){
    const [a,z]=c.span;assert.equal(a,prior);prior=z;
    assert.equal(unit.slice(a,z),c.literalNativeClause);assert.equal(sha(unit.slice(a,z)),c.nativeClauseSha256Utf8);
    for(let j=a;j<z;j++)assert.equal(coverage[j],c.selection==='retained'?1:0);
  }
  assert.equal(prior,Array.from(unit).length);
  assert.deepEqual(PRIVATE133.tuesdayClauses.filter(c=>c.selection==='documented exclusion').map(c=>c.span),[[878,1006]]);
  assert.equal(unit.slice(143,182).length,39);assert.ok(r.spans[1].rawText.includes(unit.slice(143,182)));
  assert.doesNotMatch(r.spans.map(s=>s.rawText).join('\n'),/ומאן אלין מיין עלאין בינה|רבי חייא ורבי יהודה הוו אזלי/);
  assert.equal(r.spans[0].endOffsetExclusive,409);assert.equal(r.spans[1].startOffset,0,'native amud seam conserved');
});
